(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.025+t*0.15)*8 + Math.cos(sx*0.02-t*0.4)*6;
  const w2y = Math.cos(sx*0.022-t*0.18)*8 + Math.sin(sy*0.019+t*0.32)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.8],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,6.0],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.11,2.1,1.8],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.085,1.8,5.2]
  ];
  let aS=0, iS=0, crs=0;
  for(const [sX,sY,f,sp,ph] of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    crs+=Math.sin(d*f*0.5-t*sp*0.8+ph*1.3)*Math.cos(d*f*0.3+t*sp*0.4);
  }
  const act=aS/8, inh=iS/8, cr=crs/8;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2+Math.sin((fx+fy)*0.12+t*2.5)*0.3+Math.sin((fx-fy)*0.1-t*2)*0.3+Math.sin(fx*0.08+fy*0.06-t*1.5)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.3+Math.sin(dist*0.065-ang*2+t*0.9)*0.5+Math.sin(dist*0.035+ang*5-t*2.1)*0.4;
  const pulses=Math.sin(dist*0.1-t*3)*Math.exp(-dist*0.005)+Math.sin(dist*0.08+t*2.5)*Math.exp(-dist*0.004)*0.7;
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(fx*0.3+t*2)*Math.sin(fy*0.35-t*1.5)*0.1;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cr*0.4+pulses*0.3)*2.0);
  const refined=Math.tanh((reaction+cell*0.5+micro)*1.8);
  const v=refined*0.5+0.5;
  const pal=[[5,12,45],[12,55,95],[18,110,120],[30,165,140],[180,195,60],[220,170,45],[210,110,55],[180,60,60],[120,30,65],[60,18,55],[20,12,48],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i, sf=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.65?1.0+(Math.abs(reaction)-0.65)*0.8:1.0;
  const hl=Math.max(0,reaction-0.5)*0.3;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+hl*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+hl*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+hl*20)|0)
  ];
}
